#!/usr/bin/env python3
"""
Parse Wikidata-style coordinates and produce a clean POI table.
"""

import json
import csv
import os
import re
from typing import Any, Dict, Optional, Tuple

def parse_wikidata_coordinate(coord_str: str) -> Optional[Tuple[float, float]]:
    """
    Parse Wikidata coordinate string format.

    Wikidata coordinates are typically in format like:
    "51.5074° N, 0.1278° W" or "51.5074, -0.1278"
    Or in JSON: {"latitude": 51.5074, "longitude": -0.1278}
    """
    if not coord_str:
        return None

    # Try to parse as a coordinate object with lat/lon keys
    if isinstance(coord_str, dict):
        lat = coord_str.get('latitude')
        lon = coord_str.get('longitude')
        if lat is not None and lon is not None:
            try:
                lat = float(lat)
                lon = float(lon)
                # Validate ranges
                if -90 <= lat <= 90 and -180 <= lon <= 180:
                    return (lat, lon)
            except (ValueError, TypeError):
                pass
        return None

    # Try to parse as string format: "51.5074° N, 0.1278° W"
    coord_str = str(coord_str)

    # Pattern for: number° direction, number° direction
    pattern = r'(-?\d+\.?\d*)\s*°?\s*([NSWE])\s*,\s*(-?\d+\.?\d*)\s*°?\s*([NSWE])'
    match = re.match(pattern, coord_str, re.IGNORECASE)

    if match:
        try:
            lat_str, lat_dir, lon_str, lon_dir = match.groups()
            lat = float(lat_str)
            lon = float(lon_str)

            # Convert direction to sign
            if lat_dir.upper() in ['S', 'W']:
                pass  # Keep negative if already negative, or make negative
            if lat_dir.upper() == 'S':
                lat = -abs(lat)
            if lat_dir.upper() == 'N':
                lat = abs(lat)
            if lon_dir.upper() == 'W':
                lon = -abs(lon)
            if lon_dir.upper() == 'E':
                lon = abs(lon)

            # Validate ranges
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return (lat, lon)
        except (ValueError, TypeError):
            pass

    # Try simple comma-separated format: "51.5074, -0.1278"
    parts = coord_str.split(',')
    if len(parts) == 2:
        try:
            lat = float(parts[0].strip())
            lon = float(parts[1].strip())
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return (lat, lon)
        except (ValueError, TypeError):
            pass

    return None

def extract_coordinates_from_claim(claim: Dict) -> Optional[Tuple[float, float]]:
    """Extract coordinates from a Wikidata claim structure."""
    if not isinstance(claim, dict):
        return None

    # Check for coordinates in the claim
    coord_value = claim.get('mainsnak', {}).get('datavalue', {}).get('value', {})

    if isinstance(coord_value, dict):
        # Wikidata coordinate value format
        if 'latitude' in coord_value and 'longitude' in coord_value:
            try:
                lat = float(coord_value['latitude'])
                lon = float(coord_value['longitude'])
                if -90 <= lat <= 90 and -180 <= lon <= 180:
                    return (lat, lon)
            except (ValueError, TypeError):
                pass

    return None

def get_label(item: Dict, qid: str) -> str:
    """Get label for an item, falling back to qid if missing."""
    # Try various possible label field names
    label = None

    # Check for itemLabel field
    if 'itemLabel' in item and item['itemLabel']:
        label = str(item['itemLabel'])

    # Check for label field
    if not label and 'label' in item and item['label']:
        label = str(item['label'])

    # Check for labels object (language-specific)
    if not label and 'labels' in item and isinstance(item['labels'], dict):
        # Try English first
        if 'en' in item['labels'] and item['labels']['en']:
            label = str(item['labels']['en'])
        # Try any available language
        if not label:
            for lang, val in item['labels'].items():
                if val:
                    label = str(val)
                    break

    # Check for sitelinks or other common fields
    if not label and 'name' in item and item['name']:
        label = str(item['name'])

    # Fallback to qid
    if not label:
        label = qid

    return label.strip() if label.strip() else qid

def get_poi_type(item: Dict) -> str:
    """Extract POI type from item."""
    poi_type = ""

    # Check for explicit type field
    if 'poi_type' in item and item['poi_type']:
        poi_type = str(item['poi_type'])
    elif 'type' in item and item['type']:
        poi_type = str(item['type'])
    elif 'itemType' in item and item['itemType']:
        poi_type = str(item['itemType'])

    # Check for P31 (instance of) claims
    if not poi_type and 'claims' in item and isinstance(item['claims'], dict):
        p31_claims = item['claims'].get('P31', [])
        if p31_claims:
            # Get the type label from the claim
            for claim in p31_claims:
                if isinstance(claim, dict):
                    target = claim.get('mainsnak', {}).get('target', {})
                    if isinstance(target, dict) and 'id' in target:
                        # Use the target ID as a fallback type indicator
                        poi_type = target['id']
                        break

    return poi_type if poi_type else "unknown"

def process_wikidata_file(input_path: str) -> list:
    """Process the Wikidata POI file and extract clean data."""
    pois = []

    with open(input_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Handle different possible structures
    if isinstance(data, dict):
        # Check for entities
        if 'entities' in data:
            entities = data['entities']
        # Check for items
        elif 'items' in data:
            entities = data['items']
        # The whole dict might be entities
        else:
            entities = data
    elif isinstance(data, list):
        entities = data
    else:
        return pois

    # Process each entity
    for qid, item in entities.items():
        # Skip non-dict items or items without proper structure
        if not isinstance(item, dict):
            continue

        # Ensure qid is a string
        if not isinstance(qid, str):
            qid = str(qid)

        # Get label
        label = get_label(item, qid)

        # Get POI type
        poi_type = get_poi_type(item)

        # Get coordinates
        lat = None
        lon = None

        # Try to get coordinates from various possible fields
        coord_val = None

        # Check for direct coordinate field
        if 'coordinates' in item:
            coord_val = item['coordinates']
        elif 'coords' in item:
            coord_val = item['coords']
        elif 'coordinate' in item:
            coord_val = item['coordinate']

        # Check for P625 claim (Wikidata property for coordinates)
        if not coord_val and 'claims' in item:
            p625_claims = item['claims'].get('P625', [])
            if p625_claims:
                for claim in p625_claims:
                    coord_val = extract_coordinates_from_claim(claim)
                    if coord_val:
                        break

        # Parse the coordinate value
        if coord_val:
            parsed = parse_wikidata_coordinate(coord_val)
            if parsed:
                lat, lon = parsed

        # Skip if no valid coordinates
        if lat is None or lon is None:
            continue

        # Validate ranges one more time
        if not (-90 <= lat <= 90 and -180 <= lon <= 180):
            continue

        pois.append({
            'qid': qid,
            'label': label,
            'poi_type': poi_type,
            'latitude': lat,
            'longitude': lon,
            'source': 'wikidata'
        })

    return pois

def deduplicate_pois(pois: list) -> list:
    """Remove duplicate qids, keeping the first occurrence."""
    seen = set()
    unique_pois = []

    for poi in pois:
        if poi['qid'] not in seen:
            seen.add(poi['qid'])
            unique_pois.append(poi)

    return unique_pois

def main():
    # Define paths
    input_path = 'inputs/wikidata/wikidata_pois_sample.json'
    output_path = 'outputs/t08_pois_clean.csv'

    # Ensure output directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    # Process the input file
    pois = process_wikidata_file(input_path)

    # Deduplicate by qid
    pois = deduplicate_pois(pois)

    # Write output CSV
    fieldnames = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']

    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(pois)

    print(f"Wrote {len(pois)} POIs to {output_path}")

if __name__ == '__main__':
    main()
